#include <stdio.h>
#include <stdlib.h>

#define MAX_VERTICES 6
#define MAX_EDGES 9

typedef struct {
    int a, b;
    int w;
} Edge;

static int parent[MAX_VERTICES];

static void uf_init(void) {
    for (int i = 0; i < MAX_VERTICES; ++i) parent[i] = i;
}

static int uf_find(int x) {
    if (parent[x] != x) parent[x] = uf_find(parent[x]);
    return parent[x];
}

static void uf_union(int x, int y) {
    int rx = uf_find(x);
    int ry = uf_find(y);
    if (rx != ry) parent[rx] = ry;
}

static int cmp_edge(const void *p1, const void *p2) {
    const Edge *e1 = (const Edge *)p1;
    const Edge *e2 = (const Edge *)p2;
    return e1->w - e2->w;
}

int main(int argc, char *argv[]) {
    if (argc < 2) {
        puts("INVALID_ARGS");
        return 0;
    }
    char *endptr;
    long n_long = strtol(argv[1], &endptr, 10);
    if (*endptr != '\0' || n_long < 0 || n_long > MAX_EDGES) {
        puts("INVALID_ARGS");
        return 0;
    }
    int n = (int)n_long;

    Edge edges[MAX_EDGES];
    for (int i = 0; i < n; ++i) {
        int a, b, w;
        if (scanf("%d-%d %d", &a, &b, &w) != 3) {
            puts("INVALID_ARGS");
            return 0;
        }
        if (a < 0) a = 0; if (a >= MAX_VERTICES) a = MAX_VERTICES - 1;
        if (b < 0) b = 0; if (b >= MAX_VERTICES) b = MAX_VERTICES - 1;
        edges[i].a = a;
        edges[i].b = b;
        edges[i].w = w;
    }

    qsort(edges, n, sizeof(Edge), cmp_edge);
    uf_init();
    Edge mst[MAX_VERTICES - 1];
    int mst_cnt = 0;
    int total_weight = 0;
    for (int i = 0; i < n && mst_cnt < MAX_VERTICES - 1; ++i) {
        int ra = uf_find(edges[i].a);
        int rb = uf_find(edges[i].b);
        if (ra != rb) {
            uf_union(ra, rb);
            mst[mst_cnt++] = edges[i];
            total_weight += edges[i].w;
        }
    }
    if (mst_cnt == MAX_VERTICES - 1) {
        printf("weight=%d edges=", total_weight);
        for (int i = 0; i < mst_cnt; ++i) {
            printf("%d-%d", mst[i].a, mst[i].b);
        }
        putchar('\n');
    } else {
        puts("DISCONNECTED");
    }
    return 0;
}
